// Generated by generators/guests from app/specs/guests (GU-01): the standalone
// guests of PrismAsk, PrismCurate, PrismDest, PrismGoogle, PrismGoogleLink, PrismHolon, PrismLearning, PrismModels, PrismR4, PrismResonance, PrismRoute, PrismRouter, built by tools/guests/build.sh from the modules the
// Prism compiles, so the Node suites run every request without the holo. Each
// exports holo_alloc(len) and holo_run(ptr, len) -> (outPtr << 32 | outLen);
// bytes whose SHA-256 is not the pinned one are refused before they compile.

export const GUESTS = {
  ask: { path: 'guest/ask.wasm', sha256: 'a1da3a66c40229fc558cef31655289910a022d6a87be1a4f190d75e6bb00af7a' },
  curate: { path: 'guest/curate.wasm', sha256: '461fe49cf6e105cebfbe9cad1a446f095286887240fb21a32286a6a0e2cc0e7e' },
  dest: { path: 'guest/dest.wasm', sha256: 'aeecfe69b3a5a858dceacc620a028f4d03f021d829016d564c73239d6c913fb0' },
  google: { path: 'guest/google.wasm', sha256: '063cf827337258a3fbdd6f9383aace28b07e02c592219debd077f104992fc51e' },
  googlelink: { path: 'guest/googlelink.wasm', sha256: '02504fddeeffda18303ab88fc47acc3ddea6c765ff827ea10ab42985c98ae5a5' },
  holon: { path: 'guest/holon.wasm', sha256: '9f9b37bd6c6897b555c469db2dffea3b5968781be3f2d614d9f65c998871bbe2' },
  learn: { path: 'guest/learn.wasm', sha256: '535ca001a3f98c2b97322437359a65d8b2b70c96039fcf59b3ba55c33aeff1b7' },
  model: { path: 'guest/model.wasm', sha256: 'c169a69492dbf18b035c23e956f6c22c558f3adc037cf6594d1b55c8d6f4b6d5' },
  r4: { path: 'guest/r4.wasm', sha256: '498fd26b1d071f54f8d0efe2616927846eef71632a4e49a83bce6c73967912e8' },
  resonance: { path: 'guest/resonance.wasm', sha256: '96df0cd7c0180455050632f2fa3e99081e79448a5908eeb11451d7dcdbbf7ed1' },
  route: { path: 'guest/route.wasm', sha256: '4ebcd98246fd2b087884ba759e468ad7182460877fb9806c9b18dff8d0c84459' },
  router: { path: 'guest/router.wasm', sha256: '732c68c2c347b50ccf2e27503df0d5b94c13b36c974e99ae8cb9c68cdee10170' },
};

const hex = (u8) => Array.from(u8, (b) => b.toString(16).padStart(2, '0')).join('');
const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: true });

async function compile(bytes, sha256) {
  const got = hex(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)));
  if (got !== sha256) throw Object.assign(new Error(`guest refused: fingerprint ${got} is not ${sha256}`), { code: 'later.guest' });
  return WebAssembly.compile(bytes);
}

function run(x, line) {
  const input = encoder.encode(line);
  const ptr = x.holo_alloc(input.length);
  new Uint8Array(x.memory.buffer, ptr, input.length).set(input);
  const packed = BigInt.asUintN(64, BigInt(x.holo_run(ptr, input.length)));
  return decoder.decode(new Uint8Array(x.memory.buffer, Number(packed >> 32n), Number(packed & 0xffffffffn)));
}

// One instance, kept and put back as it began before each request: its memory
// above the stack as first instantiated, and what it grew by zero. An instance
// a request trapped is dropped. So no state carries over, and asking often
// does not leave an instance behind each time.
export async function openGuest(bytes, sha256) {
  const module = await compile(bytes, sha256);
  let x = null, first = null, from = 0;
  return async (line) => {
    if (x) { const memory = new Uint8Array(x.memory.buffer); memory.set(first, from); memory.fill(0, from + first.length); }
    else { x = (await WebAssembly.instantiate(module, {})).exports; from = Number(x.__stack_high?.value ?? 0); first = new Uint8Array(x.memory.buffer).slice(from); }
    try { return run(x, line); } catch (error) { x = null; throw error; }
  };
}

// The guest as this module serves it: its bytes read from beside this file
// under Node and fetched from beside it in a browser, then opened as above.
export async function opened(guest, open = openGuest) {
  const at = new URL(guest.path, import.meta.url);
  return open(at.protocol === "file:" ? await (await import("node:fs/promises")).readFile(at) : new Uint8Array(await (await fetch(at)).arrayBuffer()), guest.sha256);
}
